  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Determine whether this booking request is valid and can be accepted according to trip availability,
   * customer booking conflicts, and the 2-hour advance rule.
   * Algorithm:
   * 1. If bookingDate is null, customer is null, or trip is null, return false.
   * 2. Verify the trip exists and has a valid departure time and the booking date/time context is usable.
   * 3. Check that numberOfSeats > 0.
   * 4. Check that trip has at least numberOfSeats remaining.
   * 5. Check that the booking is made strictly more than 2 hours before the trip departure time.
   *    - A booking exactly 2 hours before departure is invalid.
   * 6. For each existing booking of the customer:
   *    - If the booking is on the same day and its trip time overlaps with the target trip, return false.
   * 7. If all checks pass, reduce the trip seat inventory by the requested seats and return true.
   * Related Features:
   * - bookingDate
   * - numberOfSeats
   * - customer
   * - trip
   * - Booking.overlapsWith(Trip)
   * - Trip.getBookedSeats()
   * - Trip.bookSeats(int)
   * - Customer.bookings
   * Related Classes: Booking, Customer, Trip, EDate
   * Input:
   * - Uses this.bookingDate as the booking time/date.
   * - Uses this.numberOfSeats as the requested seat count; must be a positive integer.
   * - Uses this.customer as the customer making the booking; must not be null.
   * - Uses this.trip as the trip to be booked; must not be null.
   * Output:
   * - boolean:
   *   - true if the booking is eligible and the trip seat inventory is successfully reduced.
   *   - false otherwise.
   * Pre-condition:
   * - The booking object exists.
   * - If any of customer, trip, or bookingDate is null, the method shall return false.
   * - Trip time data must be present and comparable to the booking date/time.
   * Post-condition:
   * - If true is returned, the trip's remaining seats are reduced by numberOfSeats and the booking is considered accepted.
   * - If false is returned, no seat inventory change is performed.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    if (getBookingDate() == null || getCustomer() == null || getTrip() == null)
    {
      return false;
    }
    if (getNumberOfSeats() <= 0)
    {
      return false;
    }
    if (getTrip().getNumberOfSeats() < getNumberOfSeats())
    {
      return false;
    }

    Date bookingTime = getBookingDate();
    Date departureTime = parseTripDateTime(getTrip().getDepartureTime());
    if (departureTime == null)
    {
      return false;
    }

    long diffMillis = departureTime.getTime() - bookingTime.getTime();
    long twoHoursMillis = 2L * 60L * 60L * 1000L;
    if (diffMillis <= twoHoursMillis)
    {
      return false;
    }

    if (getCustomer().getBookings() != null)
    {
      for (Booking existingBooking : getCustomer().getBookings())
      {
        if (existingBooking != null && existingBooking != this && existingBooking.getTrip() != null)
        {
          if (sameDay(existingBooking.getBookingDate(), bookingTime)
              && existingBooking.overlapsWith(getTrip()))
          {
            return false;
          }
        }
      }
    }

    return getTrip().bookSeats(getNumberOfSeats());
    
  }

